static DISCRETE_4_SYNERGY_CORE_RAW_PROFILE: &str = "{\n  \"device\": {\n    \"name\": \"Antelope Discrete 4 Synergy Core\",\n    \"vid\": \"0x23e5\",\n    \"pid\": \"0xa2be\",\n    \"bcdDevice\": \"04.01\",\n    \"status\": \"confirmed\",\n    \"notes\": \"vid, pid and bcdDevice all read from the unit's own Windows PnP instance id on a machine with it attached and enumerating: USB\\\\VID_23E5&PID_A2BE carries FriendlyName \\\"Discrete 4 Synergy Core\\\", and HID\\\\VID_23E5&PID_A2BE&REV_0401&MI_03 is the vendor-defined HID interface. The vid is no longer an assumption carried over from Orion. Serial deliberately not recorded.\",\n    \"evidence\": \"Get-PnpDevice | Where-Object InstanceId -like '*VID_23E5&PID_A2BE*'\"\n  },\n  \"transport\": {\n    \"type\": \"hid\",\n    \"report_size\": 320,\n    \"out_endpoint\": \"0x01\",\n    \"in_endpoint\": \"0x82\",\n    \"interface\": 3,\n    \"poll_interval_ms\": null,\n    \"status\": \"confirmed\",\n    \"notes\": \"report_size 320 is not assumed from Orion: this model's format defines the 0x83 meter report as a 16-byte header plus afx_meters of ubyte * 304, exactly 320. Interface 3 is from the PnP instance id (MI_03). Endpoints carried over from the family and NOT separately confirmed on this unit.\",\n    \"evidence\": \"live device readback, 2026-09-01\"\n  },\n  \"frame\": {\n    \"command\": {\n      \"status\": \"unconfirmed\",\n      \"notes\": \"SET_PARAM shape (magic/opcode/param_id_offset/channel_offset/value_offset) not yet captured for this device. Do not assume it matches Orion Studio III's 0x70/0x13/16/17/18 -- confirm from a fresh capture first, per README.md step 4 (check the outgoing URB_INTERRUPT out frame, not just the state-report diff).\"\n    },\n    \"state_report\": {\n      \"status\": \"unconfirmed\",\n      \"notes\": \"Base offsets are NOT filled in, deliberately. parse_state() reads gain_base_offset, status_base_offset and status_bits without consulting status, so putting numbers there would make `status` report a gain and a phantom state that no one has checked against a real frame. The numbers below are good enough to be worth having and not good enough to act on. They are listed in unresolved_state_offsets.\",\n      \"evidence\": \"live device readback, 2026-09-01\"\n    }\n  },\n  \"params\": {},\n  \"channels\": {\n    \"count\": 4,\n    \"addressing\": \"0-indexed, written to frame.command.channel_offset\",\n    \"status\": \"confirmed\",\n    \"notes\": \"The 0x73 preamps block is a struct of count 4, one status byte per preamp, and preamp_gains beside it is byte * 4. The two agree here, unlike on the Pro where the gain array is byte * 7 for four preamps.\",\n    \"evidence\": \"live device readback, 2026-09-01\"\n  },\n  \"buses\": {\n    \"known\": {},\n    \"status\": \"unconfirmed\",\n    \"notes\": \"Output bus ids (monitor A/B, headphone, etc.) not yet captured for this device -- do not assume Orion Studio III's 0/1/2/5 mapping applies.\"\n  },\n  \"unresolved_state_offsets\": [\n    \"state_report base offsets, derived from Antelope's declared 0x73 layout but NOT yet verified against a raw frame: gain_base_offset 40 (byte * 4), status_base_offset 44 (one byte per preamp, count 4), no volumes_and_mutes block on this model at all.\",\n    \"status_bits from the same source: type mask 0x0f shift 0, phantom 0x10 shift 4, hpf 0x20 shift 5, phase_inv 0x40 shift 6, zero_cross 0x80 shift 7.\"\n  ]\n}";

