static ORION_STUDIO_3_FRAMES: &[FrameDefinition] = &[
    FrameDefinition { id: "command", kind: FrameKind::Command, status: Status::Confirmed, status_text: "confirmed", magic_offset: Some(0u16), magic: Some(112u8), opcode_offset: Some(4u16), opcode: Some(19u8), opcode_name: "SET_PARAM", fields: ORION_STUDIO_3_FRAME_0_FIELDS, operations: ORION_STUDIO_3_FRAME_0_OPERATIONS, metadata: "{\"channel_offset\":17,\"magic\":\"0x70\",\"magic_offset\":0,\"notes\":\"The general-purpose 'set one param for one target' frame. Used for every per-input-channel param (gain, mode, phantom, phase), the per-bus params (bus_level/bus_dim/bus_mute/bus_mono) and talkback_dest_assign. channel_offset means different things depending on the param: a physical input index (0-11) for channel params, a bus id (0-5, all six now identified -- see 'buses') for bus params, or a talkback destination index (0-3) for talkback_dest_assign. No known GET/query opcode -- state is read passively from IN reports. magic (byte 0) 0x70 is written for family consistency; on the sibling Discrete 8 Pro byte 0 is IGNORED on outgoing commands (offset 4 / opcode is the real discriminator there), and that most likely holds for Orion too -- byte 0 as 'the magic' is a property of the INCOMING reports (0x73/0x75/0x74), not the outgoing command.\",\"opcode\":\"0x13\",\"opcode_name\":\"SET_PARAM\",\"opcode_offset\":4,\"param_id_offset\":16,\"value_offset\":18}" },
    FrameDefinition { id: "link_command", kind: FrameKind::Command, status: Status::Confirmed, status_text: "confirmed", magic_offset: Some(0u16), magic: Some(112u8), opcode_offset: Some(4u16), opcode: Some(20u8), opcode_name: "SET_LINK", fields: ORION_STUDIO_3_FRAME_1_FIELDS, operations: ORION_STUDIO_3_FRAME_1_OPERATIONS, metadata: "{\"enabled_offset\":19,\"magic\":\"0x70\",\"magic_offset\":0,\"notes\":\"A SEPARATE frame shape from the SET_PARAM command -- do NOT build it with build_command()/build_raw_command(). param_id at 16 lines up with SET_PARAM's. Offset 17 was previously thought unused/always-0; capture spdif-gain-link (2026-08) shows it is a SPACE/DOMAIN selector: 0x00 for physical + ADAT link (which still can't be told apart from each other -- both use 0x00), 0x01 for S/PDIF link. pair_index is at 18, explicit enabled 0/1 at 19. Confirmed: chlink (all 6 physical pairs, space 0), ADAT-link1-2-7-8 (pairs 0/1/6/7, space 0), spdif-gain-link (pair 0, space 1).\",\"opcode\":\"0x14\",\"opcode_name\":\"SET_LINK\",\"opcode_offset\":4,\"pair_index_offset\":18,\"param_id\":\"0xa2\",\"param_id_offset\":16,\"space_offset\":17,\"space_values\":{\"0\":\"physical inputs AND ADAT (shared -- not distinguishable from the frame, see params.adat_channel_link.notes)\",\"1\":\"S/PDIF\",\"3\":\"virtual-mixer channel link (Mix 1-4 strips) -- CONFIRMED macos-mix1-send-pan-fader-mute-solo-link (2026-08): linking mix ch1+ch2 sent SET_LINK space=0x03 pair_index=0x00 enabled=0x01. Software-mirrored like the other link spaces -- while linked the Launcher re-sent BOTH strips' mix_command frames on every fader move.\"}}" },
    FrameDefinition { id: "routing_command", kind: FrameKind::Command, status: Status::Confirmed, status_text: "FULLY DECODED 2026-08-31, incl. READBACK. Frame model + all 12 source banks + all 15 destination channel counts confirmed. Readback: frame.readback category 0x03 -- one record per destination group (index 0..14), the exact same (bank,idx) array as the write frame. Verified end-to-end: CLI wrote line_out/hp1 from Linux, read back byte-identical from the device (and shown correctly by a fresh Windows Launcher, CAPTURE E'). CLI hardware round-trip confirmed 2026-08-31.", magic_offset: Some(0u16), magic: Some(112u8), opcode_offset: Some(4u16), opcode: Some(83u8), opcode_name: "SET_ROUTE", fields: ORION_STUDIO_3_FRAME_2_FIELDS, operations: ORION_STUDIO_3_FRAME_2_OPERATIONS, metadata: "{\"addressable_destinations\":{\"0\":\"line_out\",\"1\":\"headphone_1\",\"10\":\"mix_ch1\",\"11\":\"mix_ch2\",\"12\":\"mix_ch3\",\"13\":\"mix_ch4\",\"14\":\"surround_in\",\"2\":\"headphone_2\",\"3\":\"monitor_a\",\"4\":\"monitor_b\",\"5\":\"reamp\",\"6\":\"com_rec\",\"7\":\"adat_out\",\"8\":\"spdif_out\",\"9\":\"afx_in\"},\"addressable_destinations_note\":\"ALL 15 destination groups are now writable (2026-09-01). The first six are physical outputs; 6-14 are internal or digital and were left unwired until their channel counts were confirmed off the cat-0x03 readback. Each was live-read before wiring and the counts matched destination_channels exactly: com_rec 32, adat_out 16, spdif_out 2, afx_in 32, mix_ch1-4 32 each, surround_in 16. NOTE mix_chN (10-13) is the input side of the VIRTUAL MIXER: its 32 channels are what each of mix N's 32 strips listens to, so `route mix1 5 preamp3` chooses strip 5's source and `mix-set 1 5 --fader ...` sets that same strip's level -- two halves of one signal path (frame.mix_command, readback cat 0x04).\",\"channel_addressing\":\"The CLI addresses an output channel 1-based: `route <dest> <N> <source>` sets channel N (1..destination_channels[dest]) of that group. For stereo_destinations (hp1/hp2/mona/monb) `L` = channel 1 and `R` = channel 2 are accepted aliases. Reamp is NOT a stereo pair (Reamp 1 / Reamp 2 are separate mono outs) so use 1/2 there. `route <dest> all <s1> <s2> ...` sets every channel at once; `route <dest> mute` mutes all; `route <dest> <N> mute` mutes one.\",\"channel_list_offset\":19,\"channel_stride\":2,\"cli_support\":\"CLI `route` / `matrix-status`. `route <dest> <chan> <source>` sets ONE output channel (1-based; `L`/`R` = 1/2 for stereo_destinations) -- the other channels are read live from the device first (frame.readback cat 0x03) and every write is read back and confirmed. `route <dest> all <s1> <s2> ...` sets the whole group; `route <dest> mute` mutes all; `route <dest> <chan> mute` mutes one. `matrix-status` is a full live read of all 15 groups. Like the Launcher there is NO un-route. Source specs: preamp N -> (0x00,N-1); emumic N (N = preamp number 5-12) -> (0x01,N-5); compplay N (alias playback) -> (0x02,N-1); adat N -> (0x03,N-1); spdif L|R -> (0x04,0|1); afx N -> (0x05,N-1); mix1..4 L|R -> (0x06..0x09, 0|1); surround N -> (0x0a,N-1); osc N -> (0x0c,N-1); mute -> mute_source. Dests wired: ALL 15 (2026-09-01). line_out 16, hp1/hp2/mona/monb/reamp/spdif_out 2, adat_out/surround_in 16, com_rec/afx_in/mix_ch1-4 32. Names accept the ids in addressable_destinations (com_rec, adat_out, spdif_out, afx_in, mix_ch1..mix_ch4, surround_in). spdif_out is in stereo_destinations so L/R work there too.\",\"destination_channels\":{\"0\":16,\"1\":2,\"10\":32,\"11\":32,\"12\":32,\"13\":32,\"14\":16,\"2\":2,\"3\":2,\"4\":2,\"5\":2,\"6\":32,\"7\":16,\"8\":2,\"9\":32},\"destination_channels_note\":\"All 15 CONFIRMED 2026-08-31 by the routing readback (frame.readback category 0x03): each record is <dest_id> + destination_channels[dest_id] (bank,idx) pairs. line_out 16, hp1/hp2/mona/monb/reamp/spdif_out 2, comp_rec/afx_in/mix_ch1..4 32, adat_out/surround_in 16.\",\"destination_offset\":18,\"frame_model\":\"CORRECTED 2026-08 (captures macos-matrix-ch1-12-mute-hp1L / -hp1R). The frame is `d3 41 <dest> | <bank0> <idx0> | <bank1> <idx1> | ...` -- after destination_offset (18) it is a plain array of (source_bank, source_index) pairs, one per output channel of the destination GROUP, starting at channel_list_offset (19) with channel_stride (2). Channel 0 = L / output 1 / Reamp 1; channel 1 = R / output 2 / Reamp 2. Multichannel groups (line_out, adat_out=16, ...) simply have more pairs. mute = mute_source (bank 0x0b, idx 0); there is no 'no source' encoding. THE WHOLE GROUP IS ALWAYS SENT -- there is no single-channel frame. EVIDENCE: hp1L capture swept preamp 1-12 into HP1 L; every frame was `d3 41 01 | 00 (n-1) | 00 02` -- [19][20] = the changing L source, [21][22] = (0x00,0x02) = preamp 3, HP1 R's unchanged source. hp1R capture then swept preamp 1-12 into HP1 R; every frame was `d3 41 01 | 0b 00 | 00 (n-1)` -- [19][20] = (0x0b,0) = MUTE (HP1 L, left muted by hp1L's final frame), [21][22] = the changing R source. The two captures are sequential and the L=mute state carries between them -- decisive. Final mutes: hp1L -> `d3 41 01 | 0b 00 | 00 02` (mute L, keep R); hp1R -> `d3 41 01 | 0b 00 | 0b 00` (mute both).\",\"magic\":\"0x70\",\"magic_offset\":0,\"mono_matrix\":\"The routing matrix treats EVERY output channel independently (user-confirmed 2026-08). HP1 L and HP1 R are separate array slots; no stereo-pair concept.\",\"multichannel_channel_counts\":\"Output-channel counts per destination group (the frame carries one (bank,index) pair per channel, all sent every time): hp1/hp2/mona/monb=2, reamp=2, spdif_out=2; LINE_OUT=16 (CONFIRMED 2026-08 -- macos-matrix-afx*/surrnd*/mix1234* frames end at byte 50 = 16 pairs at bytes 19-50; caveat: a trailing channel routed to (bank 0, idx 0) would read as 00 00 and be invisible, but 16 matches the Launcher matrix). Still unknown: com_rec, adat_out (16 from the old adat_out '15x 03 NN' note), afx_in, mix_ch1..4, surround_in. Only the 2-channel groups are wired into the CLI so far. In the confirmed line_out captures, byte 18 = 0x00 and channel 0 was the one being changed; channels 1-15 held their prior routing (preamp 2-12 then compplay 1-4).\",\"mute_source\":[11,0],\"notes\":\"The matrix/routing frame -- its own command shape (opcode 0x53, NOT the SET_PARAM layout). [16]=0xd3, [17]=0x41 (constant), [18]=destination group. After that: an array of (source_bank, source_index) pairs, one per output channel of the group, from channel_list_offset (19), stride 2 -- see frame_model. Source banks in source_banks. Destination map from capture matrix-compplay-allouts-1: 0=line_out 1=hp1 2=hp2 3=mona 4=monb 5=reamp 6=com_rec 7=adat_out 8=spdif_out 9=afx_in 10-13=mix_ch1..4 14=surround_in. Routing is EXCLUSIVE per channel (one source per output channel; 'virtual mixes' are the separate summing mechanism). NO USB readback at all -- see params.routing.readback (HID descriptor has no Feature report; device STALLs GET_REPORT; preset-load is pure push).\",\"opcode\":\"0x53\",\"opcode_name\":\"SET_ROUTE\",\"opcode_offset\":4,\"param_id\":\"0xd3\",\"param_id_offset\":16,\"source_banks\":{\"0x00\":\"preamps / physical inputs (idx 0-11 = preamp 1-12)\",\"0x01\":\"emumic -- the mic-modeling ('emuMic') DSP output as a matrix source (the wet/modelled tap of a preamp, vs bank 0x00 = the dry preamp). The DSP is controlled by micmodeling_command (opcode 0x17 / param 0xe5). CONFIRMED 2026-08-31 from capture 'emumic-5to 12' (Windows KVM): routed emumic into line_out ch 1-8, one channel at a time -> pairs (0x01, 0) .. (0x01, 7). So bank 0x01 has 8 indices, 0-7. The Launcher labels them by PREAMP NUMBER 5-12 (idx 0 = preamp 5), even though the front-panel EMU button only appears on preamps 7-12 -- so emumic idx 0-1 (preamps 5-6) are selectable as matrix sources with no way to configure a model on them (a Launcher bug or an unfinished feature; UNTESTED whether the card actually produces audio on those two taps). CLI source spec: emumicN with N = preamp number 5-12 -> (0x01, N-5).\",\"0x02\":\"compplay -- Computer Playback / USB channels, idx 0 = Computer Playback 1. 24 channels on the Windows VM driver, up to 32 on the native-macOS driver (user-observed 2026-08 -- host-driver-dependent count). Named 'compplay' to match the Antelope Launcher label.\",\"0x03\":\"ADAT inputs (idx 0-15 = ADAT 1-16)\",\"0x04\":\"S/PDIF inputs (idx 0-1 = L/R)\",\"0x05\":\"AFX out -- Synergy Core FX / AFX2DAW effect returns, idx 0-31 (32 channels). CONFIRMED (macos-matrix-afx1-19-to-line1-afx29to32-to-line1, 2026-08: AFX 1-19 -> idx 0x00-0x12, AFX 29-32 -> idx 0x1c-0x1f, linear).\",\"0x06\":\"mix 1 -- virtual mix 1, idx 0 = L, 1 = R. CONFIRMED (macos-matrix-mix1234-lineo1-invphch6, 2026-08).\",\"0x07\":\"mix 2 -- virtual mix 2, idx 0/1 = L/R. CONFIRMED (same capture).\",\"0x08\":\"mix 3 -- virtual mix 3, idx 0/1 = L/R. CONFIRMED (same capture).\",\"0x09\":\"mix 4 -- virtual mix 4, idx 0/1 = L/R. CONFIRMED (same capture).\",\"0x0a\":\"surround out -- idx 0-15 (16 channels). CONFIRMED (macos-matrix-surrnd1-16-to-lineo1, 2026-08: surround 1-16 -> idx 0x00-0x0f).\",\"0x0b\":\"MUTE -- putting (bank 0x0b, idx 0) in a channel slot mutes that output channel (right-click -> mute in the matrix). User-confirmed 2026-08. Un-mute = put a real source back.\",\"0x0c\":\"oscillator (idx 0-1 = oscillator 1 / oscillator 2 -- right-click -> insert oscillator on an output)\"},\"status\":\"FULLY DECODED 2026-08-31, incl. READBACK. Frame model + all 12 source banks + all 15 destination channel counts confirmed. Readback: frame.readback category 0x03 -- one record per destination group (index 0..14), the exact same (bank,idx) array as the write frame. Verified end-to-end: CLI wrote line_out/hp1 from Linux, read back byte-identical from the device (and shown correctly by a fresh Windows Launcher, CAPTURE E'). CLI hardware round-trip confirmed 2026-08-31.\",\"stereo_destinations\":[\"1\",\"2\",\"3\",\"4\",\"8\"],\"subcmd\":\"0x41\",\"subcmd_offset\":17,\"supersedes\":\"This REPLACES the old op1_offset/op2_offset/output_ops model (bytes 21-22 = '02 01' for output 1, '00 02' for output 2). That was a misread: '00 02' is literally (bank 0x00, index 0x02) = preamp 3, i.e. the OTHER channel's untouched routing, not an opcode. The old CLI shipped this bug -- `route hp1 R preamp4` wrote preamp4 to [20] (the L slot) and preamp3 to [21][22] (R), so it set L=preamp4, R=preamp3 (user-observed on the Windows Launcher, 2026-08).\"}" },
    FrameDefinition { id: "global_command", kind: FrameKind::Command, status: Status::Confirmed, status_text: "confirmed", magic_offset: Some(0u16), magic: Some(112u8), opcode_offset: Some(4u16), opcode: Some(18u8), opcode_name: "SET_GLOBAL", fields: ORION_STUDIO_3_FRAME_3_FIELDS, operations: ORION_STUDIO_3_FRAME_3_OPERATIONS, metadata: "{\"magic\":\"0x70\",\"magic_offset\":0,\"notes\":\"A third command shape, for device-global params that have no per-channel/per-bus target. Same header as SET_PARAM but the single value byte sits at offset 17 (where SET_PARAM keeps its channel byte); offset 18 is unused/0. Confirmed from the talkback captures (2026-08): talkback_button (param 0x1f), talkback_source (param 0x27) and talkback_gain (param 0x20) all use opcode 0x12 with the value at offset 17. Build with build_global_command(profile, param_id, value) -- NOT build_command() (which would put the value at offset 18).\",\"opcode\":\"0x12\",\"opcode_name\":\"SET_GLOBAL\",\"opcode_offset\":4,\"param_id_offset\":16,\"value_offset\":17}" },
    FrameDefinition { id: "mix_command", kind: FrameKind::Command, status: Status::Confirmed, status_text: "confirmed", magic_offset: Some(0u16), magic: Some(112u8), opcode_offset: Some(4u16), opcode: Some(23u8), opcode_name: "SET_MIX", fields: ORION_STUDIO_3_FRAME_4_FIELDS, operations: ORION_STUDIO_3_FRAME_4_OPERATIONS, metadata: "{\"channel_offset\":19,\"fader_offset\":20,\"magic\":\"0x70\",\"magic_offset\":0,\"mix_offset\":18,\"mute_bit\":\"0x40\",\"notes\":\"Opcode 0x17 with param_id [16]=0xd4 -- the VIRTUAL MIXER (the Mix 1-4 windows, a SEPARATE UI from the routing matrix: mixing happens here, then Mix N's L/R appear as sources in the matrix, banks 0x06-0x09). NOTE opcode 0x17 is SHARED: param_id 0xe5 on the same opcode is mic modeling (frame.micmodeling_command) -- always check [16]. One frame per (mix, channel) strip, carrying that strip's WHOLE state every time. CONFIRMED from macos-mix1-send-pan-fader-mute-solo-link (2026-08, native macOS): [16]=0xd4 [17]=0x05 constant; [18]=mix number 0-3 (0 = Mix 1 .. 3 = Mix 4) -- CONFIRMED 2026-08-31 via the cat-0x04 readback, which returns an independent record for each of the four indices (the original capture had only ever shown mix 0); [19]=channel **0-32**: 1-32 = the input strips (each mix has 32 -- the user's solo click re-sent all 32, a handy channel-count probe) and **0 = the MIX MASTER strip** (CONFIRMED 2026-09-01 from captures/new/mix1-masterfaderplay.pcapng: sweeping the Mix 1 master fader emits 68 frames, all `d4 05 00 00 <fader> 20 60` -- channel 0, pan/send held constant. The Launcher writes channel 0 itself, so it is a normal target); [20]=FADER, raw = attenuation in -dB, 0 = 0dB/unity .. 90 = -90dB (matches the UI's 0..-90 range); [21]=PAN + FLAGS -- low 6 bits (pan_mask) = pan, pan_center 0x20, so 0x02 = full-left (-30), 0x20 = center, 0x3e = full-right (+30) i.e. raw = 32 + degrees; bit 0x40 = MUTE; bit 0x80 = SOLO; [22]=SEND level, 0-96 (0x60 = 0dB, 0 = -inf; same 0-96 scale as bus_level). No target byte past 22. READBACK: frame.readback category 0x04, index = mix number 0..3 -- FULLY DECODED + hardware round-trip verified 2026-08-31. The record is 33 three-byte slots in this frame's own field order (fader, pan|flags, send); slot N is exactly the strip written as `channel` N -- including slot 0 = channel 0 = the mix master -- so the readback and the write frame share a layout the way routing does, with no special case at either end. That round trip also confirmed [18] really is the mix number (all four mixes return their own record) and that [22] is stored send state, not a meter. protocol.parse_mixer_record; CLI `mix-status`. Also category 0x1b = mixer bus level/range table (still undecoded). CLI: `mix-set <mix> <ch|master> [--fader dB] [--pan] [--send] [--mute] [--solo]`, which read-modify-writes the strip via the cat-0x04 readback (this frame carries the WHOLE strip, so a partial write would reset the untouched fields) and verifies afterwards. Direct builder: build_mix_command(profile, mix, channel, fader, pan_deg, send, mute, solo).\",\"opcode\":\"0x17\",\"opcode_name\":\"SET_MIX\",\"opcode_offset\":4,\"pan_center\":32,\"pan_flags_offset\":21,\"pan_mask\":\"0x3f\",\"param_id\":\"0xd4\",\"param_id_offset\":16,\"send_offset\":22,\"solo_bit\":\"0x80\",\"subcmd\":\"0x05\",\"subcmd_offset\":17}" },
    FrameDefinition { id: "auraverb_command", kind: FrameKind::Decoder, status: Status::Unknown, status_text: "unknown", magic_offset: Some(0u16), magic: Some(112u8), opcode_offset: Some(4u16), opcode: Some(29u8), opcode_name: "SET_AURAVERB", fields: ORION_STUDIO_3_FRAME_5_FIELDS, operations: ORION_STUDIO_3_FRAME_5_OPERATIONS, metadata: "{\"defaults\":{\"color\":100,\"early_reflection_gain\":11,\"late_reflection_delay\":13,\"pre_delay\":0,\"reverb_level\":50,\"reverb_time\":66,\"richness\":24,\"room_size\":81},\"enabled_offset\":28,\"magic\":\"0x70\",\"magic_offset\":0,\"mix_offset\":18,\"mix_wet_constant\":100,\"mix_wet_offset\":22,\"notes\":\"Its own command shape (opcode 0x1d) -- the AuraVerb reverb on the Mix 1 window (a device-BUNDLED Synergy Core effect: always present, no per-plugin activation -- IN SCOPE, unlike the licensed AFX plugin chain). DSP PARAMS DECODED from macos-auraverb-ctl-color-predelay-earlyrefgaij-laterefdelay-richness-reverbtime-roomsize-reverblevel (2026-08-31, native macOS): the user swept each of the 8 AuraVerb controls one at a time. Frame offsets 16-28: [16]=0xda param_id; [17]=0x0b constant sub-cmd; [18]=0x00 constant (only Mix 1 captured -- likely the mix index, AuraVerb lives on a mix window); [19]=Room Size; [20]=Color; [21]=Pre-Delay (0-100 maps to 0-32 ms per the public manual); [22]=0x64 (100) constant, NEVER swept -- assumed the wet/mix amount locked at 100% (AuraVerb runs 100% wet as a mix send), could also be a 9th unexposed control; [23]=Early Reflection Gain; [24]=Late Reflection Delay; [25]=Richness; [26]=Reverb Time; [27]=Reverb Level; [28]=enabled (01 on / 00 off, from macos-auraverb-on-off). Every param is a plain 0-100 byte (UI drags land on even values, granularity 2, but odd values are presumably legal); Color reached exactly 0x64=100, the rest topped out at 0x62=98 only because the drag stopped short. The frame carries ALL 8 params + enabled every time (whole-state, like the mixer). Control names + ranges cross-checked against the Orion Studio Synergy Core user manual p.50 and antelopeaudio.com/products/auraverb (facts only). NO 0x73 readback (checked the whole capture -- only meter jitter at 125-136/235-238 moved, none tracking the swept values), so cli.py caches CLI-issued state like `route`/`set-link`. defaults[] = the device power-on values seen frozen in macos-auraverb-on-off. build_auraverb_command + CLI `auraverb`; 0x1d in constraints.allowed_opcodes (2026-08-31).\",\"opcode\":\"0x1d\",\"opcode_name\":\"SET_AURAVERB\",\"opcode_offset\":4,\"param_id\":\"0xda\",\"param_id_offset\":16,\"param_offsets\":{\"color\":20,\"early_reflection_gain\":23,\"late_reflection_delay\":24,\"pre_delay\":21,\"reverb_level\":27,\"reverb_time\":26,\"richness\":25,\"room_size\":19},\"param_range\":[0,100],\"subcmd\":\"0x0b\",\"subcmd_offset\":17}" },
    FrameDefinition { id: "micmodeling_command", kind: FrameKind::Decoder, status: Status::Unknown, status_text: "unknown", magic_offset: Some(0u16), magic: Some(112u8), opcode_offset: Some(4u16), opcode: Some(23u8), opcode_name: "SET_MIC_MODELING", fields: ORION_STUDIO_3_FRAME_6_FIELDS, operations: ORION_STUDIO_3_FRAME_6_OPERATIONS, metadata: "{\"channel_bias\":-4,\"channel_bias_note\":\"byte 18 = 0-based input channel index + channel_bias, i.e. preamp 7 (index 6) -> 2, preamp 12 (index 11) -> 7\",\"channel_offset\":18,\"channels\":[6,7,8,9,10,11],\"channels_note\":\"0-based input channel indices that have the EMU / mic-modeling button -- preamps 7-12.\",\"enabled_offset\":19,\"magic\":\"0x70\",\"magic_offset\":0,\"model_offset\":20,\"notes\":\"MIC MODELING / 'emuMic' -- the front-panel EMU button present ONLY on preamps 7-12 (6 channels). Runs Antelope's mic-emulation DSP (for their Edge Solo / Edge Duo / Edge Note modelling mics + model packs). Opcode 0x17 is SHARED: param_id at [16] disambiguates -- 0xd4 = virtual mixer (frame.mix_command), 0xe5 = mic modeling. Frame `e5 05 <ch> <en> <model> <swap> <pattern>`, bytes 16-22, rest 0. [17]=0x05 const; [18]=channel = 0-based input channel index - 4 (preamp 7 -> 2 ... preamp 12 -> 7); [19]=modeling ENABLED (1/0); [20]=MODEL ID (0 = EdgeDuo / raw mic, no emulation -- the default; 1..N = the emulation models, see profiles/mic_models.json); [21]=CHANNEL-ORDER SWAP (0/1); [22]=POLAR PATTERN, always a 0-based INDEX (NOT a class code -- corrected 2026-09-01 from macos-emumic-polar-patterns). With model 0 (EdgeDuo raw) it is the free 0-100 continuous morph (0 omni / 50 cardioid / 100 figure-8), user-confirmed. With an emulation model selected it is a small integer index into that model's pattern list, and its range is per-model: fixed mics lock it at 0 (models 2,5,6,8,13,14,15,17 -- one pattern); models 3,4,7 sweep 0..2 (omni/cardioid/fig-8); models 9,10,11 sweep 0..8 (9-detent multipattern); models 1,12,16,18 only 0..1 were swept (a 3rd value may exist -- not confirmed). Selecting a model writes [22] = that model's DEFAULT pattern index (0 for fixed, 1 = cardioid for the 3-way mics, 4 = cardioid for the 9-way mics) -- this is the value earlier misrecorded as 'pattern_class' in mic_models.json. Enable/pattern(model 0)/swap decoded 2026-08-31 from macos-ch7-8-micmodeling-* / macos-ch9-10_11-12-micmodeling-*; model IDs from 'emumic-model-select-...' (Windows KVM, 18 models cycled on preamps 7-8); per-model pattern-index ranges from macos-emumic-polar-patterns (2026-09-01, all 19 models swept on preamps 7-8). Whole state every frame; params MIRROR across the linked preamp pair (Launcher sends [18]=N then [18]=N+1). Disabling sets [19]=[21]=[22]=0. SIDE EFFECTS of enabling: the Launcher also turns on 48V phantom for the pair (SET_PARAM param 0x51) and links the preamp pair (SET_LINK space 0). No readback CATEGORY identified yet in the 0x74/0x75 protocol (the DSP-EQ categories 0x07/0x1a are unmapped -- one of them may cover this); in the passive 0x73 stream only the phantom bit (0x10) moves. build_micmodeling_command(profile, channel, enabled, pattern, swap, model); not in cli.py.\",\"opcode\":\"0x17\",\"opcode_name\":\"SET_MIC_MODELING\",\"opcode_offset\":4,\"param_id\":\"0xe5\",\"param_id_offset\":16,\"pattern_offset\":22,\"pattern_range\":[0,100],\"pattern_range_note\":\"[0,100] is the model-0 (EdgeDuo raw) continuous morph range. For a selected emulation model [22] is a small index whose max is model-dependent: 0 (fixed), 2 (3-way), or 8 (9-detent multipattern). See notes and mic_models.json.\",\"subcmd\":\"0x05\",\"subcmd_offset\":17,\"swap_offset\":21}" },
    FrameDefinition { id: "state_report", kind: FrameKind::StateReport, status: Status::Confirmed, status_text: "confirmed", magic_offset: Some(0u16), magic: Some(115u8), opcode_offset: None, opcode: None, opcode_name: "", fields: ORION_STUDIO_3_FRAME_7_FIELDS, operations: ORION_STUDIO_3_FRAME_7_OPERATIONS, metadata: "{\"adat_gain_base_offset\":75,\"bus_block\":{\"base_offset\":28,\"bytes_per_bus\":3,\"level_byte_offset\":0,\"notes\":\"Same 'parallel array, N bytes per slot' idea as gain_base_offset/status_base_offset above, but for output buses instead of input channels: byte offset for bus N = base_offset + bytes_per_bus*N + field_offset. Confirmed for ALL 6 bus ids: 0/1/2/5 via captures mona/hp1/hp2/monb (2026-08, level ramps + dim/mute/mono toggles), and 3/4 (line/reamp) via capture settings-linevol-mute-reampvol-toggle (2026-08, level ramps at offsets 37 and 40 + a mute toggle on bus 3). Every SET_PARAM command in each log matched the very next state_report reading at this formula's offset. reserved_byte_offset (+2) never changed in any capture; true padding, or just never exercised, is unconfirmed. dim/mono were never exercised on buses 3/4 and may not apply to a line/reamp output. NOTE: the status byte's mute bit (0x04) also reads 1 whenever that bus is at level 96 with no mute command -- see params.bus_mute.\",\"reserved_byte_offset\":2,\"status_bits\":{\"dim\":{\"mask\":\"0x08\",\"shift\":3},\"mono\":{\"mask\":\"0x10\",\"shift\":4},\"mute\":{\"mask\":\"0x04\",\"shift\":2}},\"status_byte_offset\":1},\"channel_meter_base_offset\":157,\"channel_meter_notes\":\"CONFIRMED 2026-09-01 (dedicated vumeter recapture): the real per-channel input meters live HERE in the 0x73 state report, at 157 + channel_index for the 12 physical channels. Feeding preamps 1/2/3/4 in turn dropped offsets 157/158/159/160 to the single digits one after another, each returning to ~96 when the tone stopped; unfed channels stayed at 96 / noise-floor jitter. Three identical mirror copies of the whole 12-byte block exist at bases 157, 169 and 221 -- use 157. This supersedes meter_report.channel_meter_base_offset (0x75 @32), which on this unit is NOT per-channel: only its byte 32 is live (a monitor/summed level) and byte 33 is a 0/1 flag that the old 32+channel formula misreads as channel 1 pinned at clip. Resolves the unresolved_state_offsets '157/169/221' entry.\",\"channel_meter_scale\":\"inverted: 0x60 (96) at rest/silence, falls toward 0x00 as level rises. Same scale as meter_report.db_curve (raw ~= -dBFS), reuse that curve.\",\"gain_base_offset\":49,\"magic\":\"0x73\",\"magic_offset\":0,\"notes\":\"Parallel-array layout: all channel gains contiguous from gain_base_offset, all status bytes contiguous from status_base_offset. Formula: status_byte = (phase<<6)|(phantom<<4)|(mode&0x03).\",\"output_trim_block\":{\"byte_offsets\":[24,25],\"fields\":{\"target_0\":{\"byte_offset\":24,\"mask\":\"0x70\",\"notes\":\"3-bit field, value<<4 at offset 24. capture settings-trim-mona-monb-line-panlaw (2026-08): SET_PARAM(0x4b, target=0, value 0..6) -> offset 24 stepped 0x00/0x10/0x20/0x30/0x40/0x50/0x60, i.e. exactly value<<4, every step. Almost certainly the Monitor A output trim (first target swept, capture name order mona/monb/line).\",\"shift\":4},\"target_1\":{\"byte_offset\":25,\"mask\":\"0x1c\",\"notes\":\"3-bit field, value<<2 at offset 25 bits 2-4. Same capture: SET_PARAM(0x4b, target=1, value 0..6) -> 0x00/0x04/0x08/0x0c/0x10/0x14/0x18. Almost certainly Monitor B output trim.\",\"shift\":2},\"target_2\":{\"byte_offset\":25,\"mask\":\"0xe0\",\"notes\":\"3-bit field, value<<5 at offset 25 bits 5-7. Same capture: SET_PARAM(0x4b, target=2, value 0..6) -> 0x00/0x20/0x40/0x60/0x80/0xa0/0xc0. Almost certainly Line output trim.\",\"shift\":5}},\"notes\":\"A small packed block just before bus_block, holding the settings-tab output-trim selectors (param 0x4b). Three targets (0/1/2) confirmed, each a 7-position selector (value 0-6) -- the physical meaning of the 7 steps (dB values? reference levels?) is not known, only that the readback is value<<shift. UNUSED bits so far: offset 24 bits 0-3 and 7, offset 25 bits 0-1 -- offset 25 bits 0-1 (a 2-bit field, 4 options) is a plausible home for the PAN LAW setting, and offset 24 bits 0-3 for a 4th trim target, but the capture named 'panlaw' never actually sent a 4th target or any other param, so pan law is still uncaptured. See params.output_trim.\"},\"sample_rate_byte_offset\":{\"notes\":\"The device sample-rate INDEX (0-6, see params.sample_rate.values), one plain byte. CONFIRMED from capture macos-smplrt-32k-44k1-48-88k2-96k-176k4-192k (2026-08, native macOS): the user stepped 32k/44k1/48k/88k2/96k/176k4/192k; each SET_GLOBAL(param 0x03, value V) was followed ~1 s later (device clock re-lock settle) by offset 18 == V, monotonic 0..6. This overlaps the old 'offset 17/19 blip' region -- offset 18 itself is the sample rate, NOT blip noise; 17 and 19 are still the ~3 s Launcher-handshake blip. Also-moved-at-88k2/176k4 offsets 21/22/23/27 are undecoded clock/PLL/buffer state (see unresolved_state_offsets). See params.sample_rate.\",\"offset\":18},\"screen_brightness_byte_offset\":{\"notes\":\"The device's front-panel screen brightness, 0-100 (0x00-0x64), one plain byte. CONFIRMED from capture macos-scrbrght-0-100-50-multvalue (2026-08, native macOS -- the user watched the physical screen dim/brighten in real time): every SET_PARAM(opcode 0x12, param 0x0e, value V) was followed by offset 26 == V in the very next 0x73 report, 25/25 commands, values 0x00..0x64. So screen brightness IS a real, persisted, readable device setting (NOT host-side -- the earlier settings-scrbrght-surroundEQ capture under the VM simply never reached the device / the slider did nothing under the VM). Sits in the previously-unmapped gap between output_trim_block (24-25) and bus_block (28-45). Offset 27 still unmapped. See params.screen_brightness.\",\"offset\":26},\"spdif_gain_base_offset\":91,\"status_base_offset\":61,\"status_bits\":{\"input_mode\":{\"mask\":\"0x03\",\"shift\":0},\"phantom\":{\"mask\":\"0x10\",\"shift\":4},\"phase_invert\":{\"mask\":\"0x40\",\"shift\":6}},\"talkback_block\":{\"gain_byte_offset\":74,\"notes\":\"Sits immediately after the 12-byte channel status array (status_base_offset 61 + 12 = 73). offset 73 is a packed talkback status byte (see status_bits); offset 74 is the talkback gain (0-96, same scale as bus_level, 96=0dB) of the CURRENTLY SELECTED source -- confirmed from talkback-gain-int-ch1-2-12 (2026-08): sweeping param 0x20 moved offset 74 1:1 across 0-96, and re-selecting the source reset offset 74 to that source's own stored gain (so talkback gain is per-source, but only the selected source's value is visible here). CAVEAT: source_low and dest_assign share bits 2-3 (source index 4-12 sets bits that also mean dest0/dest1 assigned). The talkback-select and talkback-bttn captures were separate sessions -- source was 0 during the dest toggles and no dest/button was set during the source sweep -- so how these coexist in one byte when both are non-default is UNTESTED. Needs a combined capture before trusting the readback with talkback fully configured.\",\"status_bits\":{\"button\":{\"mask\":\"0x40\",\"notes\":\"Talkback button / hold-to-talk active. Confirmed from capture talkback-bttn (2026-08): press -> bit 6 set, release -> cleared, every time.\",\"shift\":6},\"dest_assign\":{\"mask\":\"0x3c\",\"notes\":\"4-bit bitmask, one bit per talkback destination (Mon A / Mon B / HP1 / HP2): destination N assigned = bit (N+2), i.e. dest0=0x04, dest1=0x08, dest2=0x10, dest3=0x20. Confirmed from capture talkback-bttn (2026-08): toggling each of the 4 switches in isolation set/cleared exactly its bit. Multi-destination combining is USER-CONFIRMED (2026-08) -- talkback can be sent to all 4 at once, so this byte can legitimately hold several of these bits set together.\",\"shift\":2},\"source_low\":{\"mask\":\"0x03\",\"notes\":\"LOW 2 BITS of the talkback source index only. Confirmed from capture talkback-select (2026-08): selecting sources 0..12 in turn, offset 73 bits 0-1 always equalled source_index & 0x03 (13/13 samples). The high bits of the source index are NOT exposed anywhere found in the 0x73 report -- offsets 72 and 75 stayed 0x00 for the whole sweep. So you can read talkback source back only mod 4 from the device; track the full value client-side.\",\"shift\":0}},\"status_byte_offset\":73}}" },
    FrameDefinition { id: "meter_report", kind: FrameKind::MeterReport, status: Status::Unknown, status_text: "superseded_for_per_channel", magic_offset: Some(0u16), magic: Some(117u8), opcode_offset: None, opcode: None, opcode_name: "", fields: ORION_STUDIO_3_FRAME_8_FIELDS, operations: ORION_STUDIO_3_FRAME_8_OPERATIONS, metadata: "{\"channel_meter_base_offset\":32,\"channel_meter_scale\":\"inverted: 0x60 (96) at rest/silence, falls toward 0x00 as level rises\",\"db_curve\":[[0,0],[10,-10],[12,-12],[20,-20],[30,-30],[40,-40],[60,-60]],\"db_curve_notes\":\"Channel 0 only, 1kHz sine, gain swept down from max while phase_invert was clicked as a timestamp marker at each reference point (a real command, so it shows up as an unambiguous status-byte bit flip -- a cheap way to bookmark a capture without a second command-frame log). Raw byte == -dB, essentially exactly, across the whole 0 to -60dB range swept (the -60 point originally logged as raw=59, not 60, but that was the user eyeballing a color bar rather than a number while manually dragging the gain slider -- not curve non-linearity, corrected to 60). Not yet swept: the red/orange LED boundary, and anything past -60dB (one stray, unexplained data point -- raw=72 at gain driven to 0/deep silence -- doesn't fit this line at all, but wasn't a deliberate reference point, see notes above). Not yet confirmed on other channels, but likely identical given the same offset formula holds for all 12.\",\"led_scale\":{\"bands\":[{\"clip\":true,\"color\":\"red\",\"max_db\":null,\"min_db\":0},{\"clip\":false,\"color\":\"orange\",\"max_db\":0,\"min_db\":-4},{\"clip\":false,\"color\":\"yellow\",\"max_db\":-4,\"min_db\":-12},{\"clip\":false,\"color\":\"green\",\"max_db\":-12,\"min_db\":null}],\"clip_at_db\":0,\"notes\":\"Confirmed 2026-08: no separate solid-red band below clip -- orange runs all the way to 0dB, red only appears at clip.\"},\"magic\":\"0x75\",\"magic_offset\":0,\"notes\":\"CORRECTED 2026-09-01: on this unit the 0x75 frame is NOT a per-channel meter. Only byte 32 is live -- a monitor/summed level that moves for any input -- and byte 33 is a 0/1 flag. The old '32 + channel, confirmed for all 12' claim was wrong: a dedicated recapture feeding preamps 1-4 in turn showed no movement past byte 32, and the byte-33 flag was rendered as channel 1 stuck at clip. The real per-channel input meters are in the 0x73 state report -- see state_report.channel_meter_base_offset (157 + channel). db_curve below (raw ~= -dBFS) still applies to those. Kept here for the offset-32 monitor reading and the shared curve.\",\"status\":\"superseded_for_per_channel\"}" },
    FrameDefinition { id: "init_enumeration_report", kind: FrameKind::InitEnumerationReport, status: Status::Unconfirmed, status_text: "unconfirmed", magic_offset: Some(0u16), magic: Some(116u8), opcode_offset: None, opcode: None, opcode_name: "", fields: ORION_STUDIO_3_FRAME_9_FIELDS, operations: ORION_STUDIO_3_FRAME_9_OPERATIONS, metadata: "{\"magic\":\"0x74\",\"magic_offset\":0,\"notes\":\"This burst IS the readback protocol (frame.readback) -- the Launcher walking every (category, index). Decoded 2026-08-31: the host SENDS a 0x74 request `74 00 00 00 10 00 00 00 <cat> 00 00 00 <idx> 00 00 00` on EP 0x01 OUT and the device REPLIES with `75 00 00 00 40 01 00 00 <cat> ... <idx> ... <data>` on EP 0x82 IN. It is not names-only and not one-shot -- it carries live state (routing = cat 0x03, mixer = cat 0x04, AuraVerb = cat 0x0a, ...). The text below is the original (pre-decode) analysis of the connect burst, kept for the emission-order detail. A one-shot device topology enumeration. Seen ONLY in all_reports_AntelopeINIT.tsv (113 records, t=7.5-16s of the connect sequence), never in any other capture. That capture is the Antelope Launcher being launched with NO user interaction (confirmed by the user) -- so this whole burst, and the single outgoing 0x70/SET_PARAM(param 0x49) at t=7.71s, is the Launcher's automatic startup/handshake, not anything a user did. Full emission order (see PROTOCOL.md section 4): 0x11 x2 (S/PDIF); 0x0b marker; 0x1b x1 singleton; 0x1a x16 (ADAT -- confirmed); 0x03 x15 (unmapped); 0x04 x4 (unmapped, each entry trailed by its own 0x0b=3 marker); 0x0a x1, 0x15 x1, 0x16 x1 singletons; 0x19 x64 (unmapped -- almost certainly the 64-channel USB/Thunderbolt stream, the device's headline I/O count; routing command's first payload byte 0x41=65 is consistent with a 1-based index into a 64-entry space); 0x0b closing markers. 0x0b (8 records, index values 1/2/3/3/3/3/0/4) is a section/phase marker, NOT an I/O category. Confirmed: 0x1a=ADAT, 0x11=S/PDIF. Still unnamed: 0x19/0x03/0x04 and the four singletons. NOTE (2026-08): checked all 21 raw pcapng files -- NOT ONE contains a USB string-descriptor fetch, and the UAC2 descriptor is a stub with no channel names. So the names are Launcher-internal and cannot be recovered from any capture on file; the practical routes are (a) a fresh connect capture where Windows re-fetches string descriptors, or (b) reading the counts off against the Launcher's routing-tab labels. This is NOT a live settings readback -- indices only, no current values. Listed here mainly so scan tools stop flagging 0x74 as unknown. CROSS-PLATFORM CONFIRMED (2026-08): the four native-macOS INIT captures (macos-antelopeINIT-*) reproduce this exactly -- same 0x74 burst (byte-identical between captures with different device state), and the SAME single outgoing handshake frame SET_PARAM(param 0x49, channel 1, value 0). That one 0x49 frame is the ENTIRE host->device connect handshake; everything else the Launcher does at connect is either passive polling or cosmetic state restore (a SET_PARAM(gain 0x50) fade-in ramp). macOS capture layout: 40-byte Darwin pseudo-header + 320-byte payload (frame.len==360), payload byte 0 = magic; 0x74 arrives on IN endpoint 1, 0x73/0x75 on IN endpoint 2.\",\"record_layout\":\"header 0x74, u32 constant 0x10 @4, u32 category_id @8, u32 index @12 (0-based, 0..count-1 within a category); nothing non-zero past offset 16. Records carry (category_id, index) ONLY -- no names (names would be USB string descriptors, i.e. control transfers, not in the 320-byte HID capture).\",\"status\":\"unconfirmed\"}" },
    FrameDefinition { id: "readback", kind: FrameKind::Decoder, status: Status::Confirmed, status_text: "confirmed", magic_offset: Some(0u16), magic: None, opcode_offset: None, opcode: None, opcode_name: "", fields: ORION_STUDIO_3_FRAME_10_FIELDS, operations: ORION_STUDIO_3_FRAME_10_OPERATIONS, metadata: "{\"categories\":{\"0x00\":\"device id + firmware (ascii '4.41' seen)\",\"0x01\":\"model name ('OrionStudio_III') + serial + hw rev ('7.0') -- CONTAINS THE DEVICE SERIAL, do not commit raw dumps\",\"0x02\":\"per-channel present flag (scalar 0x01), indexed 0..63\",\"0x03\":\"ROUTING MATRIX -- one record per destination group, index = dest_id 0..14. Record = <dest_id> then a (source_bank, source_index) pair per output channel of that group (destination_channels[dest_id] pairs), identical layout to the frame.routing_command write frame. VERIFIED byte-identical against CLI-written routes 2026-08-31.\",\"0x04\":\"VIRTUAL MIXER -- one record per mix, index = mix number 0..3 (= Mix 1..4). Record = a flat array of 33 three-byte slots, SAME field order as the frame.mix_command write frame: <fader> <pan|mute|solo> <send>. Slot index maps 1:1 onto frame.mix_command's `channel` field with NO special case: slot 0 = the MIX MASTER strip, slots 1..32 = the 32 input strips. 99 bytes on the wire, zero-padded to the report size. DECODED + HARDWARE-CONFIRMED, both halves. (a) INPUTS, 2026-08-31: wrote mix 1 / ch 5 / fader 40 / pan +12 / mute / send 33 (frame bytes `28 6c 21`), read the record back and slot 5 was `28 6c 21` with NO other slot changed; three reads 2.5s apart -- and later 142 reads over 150s -- were byte-identical, so the third byte is stored send state and not a live meter. (b) MASTER, 2026-09-01: a usbmon capture of the Launcher sweeping the Mix 1 master fader (captures/new/mix1-masterfaderplay.pcapng) is 68 frames, every one `d4 05 00 00 <fader> 20 60` -- mix 0, CHANNEL 0, pan and send constant; the sweep ended at fader 90 and slot 0 then read back as -90 dB. The Launcher itself addresses channel 0, so it is a normal target and NOT an out-of-range write. protocol.parse_mixer_record; CLI `mix-status`. This is the mixer readback that frame.mix_command's notes used to say did not exist -- it is not in the 0x73 state report, it is here.\",\"0x05\":\"preamp channel summary (gain/status), ~12 bytes\",\"0x06\":\"channel status bits (mirrors state_report offsets 61+)\",\"0x07\":\"EQ curve -- frequency points ~30/200/1k/5k/15k Hz, 8 records. Channel or surround EQ. Undecoded.\",\"0x0a\":\"AuraVerb parameters (mirrors frame.auraverb_command payload). Partially decoded.\",\"0x0b\":\"scalar 0x01\",\"0x0c\":\"~90-entry per-channel link/config table. Undecoded.\",\"0x0d\":\"scalar (0x18)\",\"0x11\":\"S/PDIF + a capability bitmask block (128 bytes)\",\"0x12\":\"scalar (clock source or sample-rate index?)\",\"0x15\":\"~90-entry table, sibling of 0x0c\",\"0x16\":\"output trim / pan-law scalars (two 0x32 values + flags)\",\"0x19\":\"64 entries, all empty in the connect walk -- the 64-ch USB/TB stream slots\",\"0x1a\":\"EQ curve, 8 bands x freq points ~30..14000 Hz (116 bytes). Undecoded.\",\"0x1b\":\"mixer bus level/range table (repeating 50 00 50 00 58 02 00). Undecoded.\",\"note\":\"Categories 0x1c..0x60 answer but with empty bodies (probed 2026-08-31). Full raw enumeration: tools/readback_enum.py.\"},\"category_counts\":{\"0x03\":15,\"0x04\":4,\"0x0a\":1,\"0x0b\":8,\"0x11\":2,\"0x15\":1,\"0x16\":1,\"0x19\":64,\"0x1a\":16,\"0x1b\":1},\"category_counts_note\":\"Record counts taken from the device's OWN 0x74 connect enumeration (frame.init_enumeration_report -- 113 records = 16+2+64+15+4+4+8, so these ten categories are the whole walk). This is the only evidence-grade count we have and it is the safe query bound (see .hazard). Categories that answer but do NOT appear in the connect walk (0x00, 0x01, 0x02, 0x05, 0x06, 0x07, 0x0c, 0x0d, 0x12) have NO known count -- protocol.build_readback_query cannot bound them, so treat any index above 0 on those as unproven and dangerous. Note that cat 0x03 answers with distinct bodies at idx 15-24 even though it only has 15 destination groups: that is already adjacent memory, not extra routing data.\",\"category_offset\":8,\"cli\":\"protocol.build_readback_query (bounds-checked) / check_readback_index / readback_category_count / is_readback_response / readback_body / parse_routing_record (cat 0x03) / parse_mixer_record (cat 0x04); transport.HidTransport.query; CLI `readback <cat> [idx]` (raw), `matrix-status` (live cat-0x03 read, falls back to the cache if the device is unreachable) and `mix-status [mix]` (live cat-0x04 read).\",\"data_offset\":16,\"discriminator_note\":\"The response magic is 0x75 but byte 1 = 0x00. The free-running METER report is also magic 0x75 but byte 1 = 0x1f; the STATE report (frame.state_report) is the same family with magic 0x73 -- effectively 'category 0, pushed continuously'. So (magic 0x75 AND byte1 0x00 AND category AND index) uniquely identifies a readback response amid the ~250 Hz state/meter stream.\",\"hazard\":\"DO NOT QUERY AN INDEX PAST A CATEGORY'S RECORD COUNT. The firmware does not bounds-check the index: one index past the end returns adjacent memory with a WRONG layout, and a little further it faults. Confirmed 2026-08-31 on real hardware -- `category 0x04 index 5` hard-crashed the Orion Studio III (front panel: 'CRITICAL ERROR! / Failure.c / L: 204  E: 0 / BusFault_Handler' -- a Cortex-M BusFault) and the unit needed a physical power cycle. Diagnostic signature, in order: cat 0x04 idx 0-3 = four same-layout mixer records; idx 4 = answers but with a completely different layout (a float32 table = adjacent memory); idx 5 = NO response at all, then the OUT endpoint is dead. An EMPTY answer is normal; NO answer means the MCU just died inside the handler. NOTE: this supersedes the earlier diagnosis that the endpoint halt was caused by 'hammering' / query rate -- the 2026-08-31 crash took about ten slow queries. Rate was never the trigger; the out-of-range index was. Enforced by protocol.check_readback_index against readback.category_counts.\",\"history\":\"Before 2026-08-31 the project concluded there was NO USB readback (see params.routing.readback, PROTOCOL.md, the -poke test). That was wrong: the request just needs the 10-00-00-00 sub-header + a (category,index) -- a bare 0x74 is ignored. The cross-machine persistence the user reported was the device reporting its NVRAM routing to a fresh Launcher via exactly this, not account sync.\",\"identity\":{\"_comment\":\"LAYOUT ONLY -- the serial VALUE is never stored in this repo. It is read from the hardware on request (CLI `identity --serial`). Same record shape on the Orion Studio III and the Zen Go Synergy Core, so it is probably family-wide.\",\"category\":\"0x01\",\"firmware_category\":\"0x00\",\"firmware_offset\":8,\"name_offset\":0,\"notes\":\"Category 0x01 is a 48-byte record of NUL-terminated ASCII at fixed offsets: model name @0, SERIAL @20 (13 chars), hardware revision @36, then 4 binary bytes @44 (little-endian u32; both units seen decode to mid-2021, so plausibly a build/calibration timestamp -- a GUESS, not confirmed). Category 0x00 is a separate record: 12 bytes with an ASCII firmware version at offset 8 (e.g. '4.41'). Parsed by protocol.parse_identity_record / parse_firmware_record.\",\"revision_offset\":36,\"serial_offset\":20,\"stamp_offset\":44},\"index_offset\":12,\"liveness\":\"The device answers EVERY (category, index) that is IN RANGE -- one it has no record for just comes back with an empty body. 'has a non-empty body' is the real liveness signal. Scalar categories return the same record for every index. Pace queries and reopen on halt (tools/readback_enum.py, transport.HidTransport.query).\",\"magic_offset\":0,\"request\":\"host->device, EP 0x01 OUT, full 320-byte report: 74 00 00 00 | 10 00 00 00 | <category> 00 00 00 | <index> 00 00 00 | 00...  (magic 0x74 @0, subcmd 0x10 @4, category @8, index @12)\",\"request_magic\":\"0x74\",\"response\":\"device->host, EP 0x82 IN, full 320-byte report: 75 00 00 00 | 40 01 00 00 | <category> 00 00 00 | <index> 00 00 00 | <data...>  (magic 0x75 @0, discriminator 0x00 @1, category @8, index @12, payload from @16)\",\"response_discriminator\":\"0x00\",\"response_discriminator_offset\":1,\"response_magic\":\"0x75\",\"status\":\"DECODED 2026-08-31 (CAPTURE E' -- usbmon on the Linux host while the Windows Launcher connected over QEMU USB passthrough -- then replayed directly from Linux, tools/readback_enum.py). This is the device-side readback the earlier analysis had concluded did not exist. It is an in-band request/response on the SAME HID interrupt endpoints, NOT a HID Feature report and NOT a control transfer -- which is why tools/hid_probe.py (no Feature report, GET_REPORT STALLs) and tools/readback_probe.py did not find it.\",\"subcmd\":\"0x10\",\"subcmd_offset\":4}" },
    FrameDefinition { id: "error_response", kind: FrameKind::ErrorResponse, status: Status::Unconfirmed, status_text: "unconfirmed on Orion -- confirmed on the sibling Discrete 8 Pro", magic_offset: Some(0u16), magic: Some(97u8), opcode_offset: None, opcode: None, opcode_name: "", fields: ORION_STUDIO_3_FRAME_11_FIELDS, operations: ORION_STUDIO_3_FRAME_11_OPERATIONS, metadata: "{\"magic\":\"0x61\",\"magic_offset\":0,\"notes\":\"On the Discrete 8 Pro (peer PR): the device replies with a 0x61 frame (status byte at offset 4) ONLY when it receives an opcode it does not recognise; a recognised opcode is answered with silence. IMPORTANT: silence means 'opcode recognised', NOT 'command took effect' -- on that device opcode 0x14 was silent and did nothing. No 0x61 frame has ever appeared in an Orion capture (only 0x70/0x73/0x75/0x74), but the Launcher never sends Orion a bad opcode, so absence is not evidence. If you ever probe a candidate opcode on Orion, watch for a 0x61 reply -- and don't read silence as success.\",\"status\":\"unconfirmed on Orion -- confirmed on the sibling Discrete 8 Pro\",\"status_offset\":4,\"status_values\":{\"0x10\":\"unknown opcode\"}}" },
];
static ORION_STUDIO_3_DECODERS: &[DecoderDefinition] = &[
    DecoderDefinition { id: "decode_auraverb_command", frame_id: "auraverb_command", kind: FrameKind::Decoder, status: Status::Unknown, metadata: "{\"defaults\":{\"color\":100,\"early_reflection_gain\":11,\"late_reflection_delay\":13,\"pre_delay\":0,\"reverb_level\":50,\"reverb_time\":66,\"richness\":24,\"room_size\":81},\"enabled_offset\":28,\"magic\":\"0x70\",\"magic_offset\":0,\"mix_offset\":18,\"mix_wet_constant\":100,\"mix_wet_offset\":22,\"notes\":\"Its own command shape (opcode 0x1d) -- the AuraVerb reverb on the Mix 1 window (a device-BUNDLED Synergy Core effect: always present, no per-plugin activation -- IN SCOPE, unlike the licensed AFX plugin chain). DSP PARAMS DECODED from macos-auraverb-ctl-color-predelay-earlyrefgaij-laterefdelay-richness-reverbtime-roomsize-reverblevel (2026-08-31, native macOS): the user swept each of the 8 AuraVerb controls one at a time. Frame offsets 16-28: [16]=0xda param_id; [17]=0x0b constant sub-cmd; [18]=0x00 constant (only Mix 1 captured -- likely the mix index, AuraVerb lives on a mix window); [19]=Room Size; [20]=Color; [21]=Pre-Delay (0-100 maps to 0-32 ms per the public manual); [22]=0x64 (100) constant, NEVER swept -- assumed the wet/mix amount locked at 100% (AuraVerb runs 100% wet as a mix send), could also be a 9th unexposed control; [23]=Early Reflection Gain; [24]=Late Reflection Delay; [25]=Richness; [26]=Reverb Time; [27]=Reverb Level; [28]=enabled (01 on / 00 off, from macos-auraverb-on-off). Every param is a plain 0-100 byte (UI drags land on even values, granularity 2, but odd values are presumably legal); Color reached exactly 0x64=100, the rest topped out at 0x62=98 only because the drag stopped short. The frame carries ALL 8 params + enabled every time (whole-state, like the mixer). Control names + ranges cross-checked against the Orion Studio Synergy Core user manual p.50 and antelopeaudio.com/products/auraverb (facts only). NO 0x73 readback (checked the whole capture -- only meter jitter at 125-136/235-238 moved, none tracking the swept values), so cli.py caches CLI-issued state like `route`/`set-link`. defaults[] = the device power-on values seen frozen in macos-auraverb-on-off. build_auraverb_command + CLI `auraverb`; 0x1d in constraints.allowed_opcodes (2026-08-31).\",\"opcode\":\"0x1d\",\"opcode_name\":\"SET_AURAVERB\",\"opcode_offset\":4,\"param_id\":\"0xda\",\"param_id_offset\":16,\"param_offsets\":{\"color\":20,\"early_reflection_gain\":23,\"late_reflection_delay\":24,\"pre_delay\":21,\"reverb_level\":27,\"reverb_time\":26,\"richness\":25,\"room_size\":19},\"param_range\":[0,100],\"subcmd\":\"0x0b\",\"subcmd_offset\":17}" },
    DecoderDefinition { id: "decode_micmodeling_command", frame_id: "micmodeling_command", kind: FrameKind::Decoder, status: Status::Unknown, metadata: "{\"channel_bias\":-4,\"channel_bias_note\":\"byte 18 = 0-based input channel index + channel_bias, i.e. preamp 7 (index 6) -> 2, preamp 12 (index 11) -> 7\",\"channel_offset\":18,\"channels\":[6,7,8,9,10,11],\"channels_note\":\"0-based input channel indices that have the EMU / mic-modeling button -- preamps 7-12.\",\"enabled_offset\":19,\"magic\":\"0x70\",\"magic_offset\":0,\"model_offset\":20,\"notes\":\"MIC MODELING / 'emuMic' -- the front-panel EMU button present ONLY on preamps 7-12 (6 channels). Runs Antelope's mic-emulation DSP (for their Edge Solo / Edge Duo / Edge Note modelling mics + model packs). Opcode 0x17 is SHARED: param_id at [16] disambiguates -- 0xd4 = virtual mixer (frame.mix_command), 0xe5 = mic modeling. Frame `e5 05 <ch> <en> <model> <swap> <pattern>`, bytes 16-22, rest 0. [17]=0x05 const; [18]=channel = 0-based input channel index - 4 (preamp 7 -> 2 ... preamp 12 -> 7); [19]=modeling ENABLED (1/0); [20]=MODEL ID (0 = EdgeDuo / raw mic, no emulation -- the default; 1..N = the emulation models, see profiles/mic_models.json); [21]=CHANNEL-ORDER SWAP (0/1); [22]=POLAR PATTERN, always a 0-based INDEX (NOT a class code -- corrected 2026-09-01 from macos-emumic-polar-patterns). With model 0 (EdgeDuo raw) it is the free 0-100 continuous morph (0 omni / 50 cardioid / 100 figure-8), user-confirmed. With an emulation model selected it is a small integer index into that model's pattern list, and its range is per-model: fixed mics lock it at 0 (models 2,5,6,8,13,14,15,17 -- one pattern); models 3,4,7 sweep 0..2 (omni/cardioid/fig-8); models 9,10,11 sweep 0..8 (9-detent multipattern); models 1,12,16,18 only 0..1 were swept (a 3rd value may exist -- not confirmed). Selecting a model writes [22] = that model's DEFAULT pattern index (0 for fixed, 1 = cardioid for the 3-way mics, 4 = cardioid for the 9-way mics) -- this is the value earlier misrecorded as 'pattern_class' in mic_models.json. Enable/pattern(model 0)/swap decoded 2026-08-31 from macos-ch7-8-micmodeling-* / macos-ch9-10_11-12-micmodeling-*; model IDs from 'emumic-model-select-...' (Windows KVM, 18 models cycled on preamps 7-8); per-model pattern-index ranges from macos-emumic-polar-patterns (2026-09-01, all 19 models swept on preamps 7-8). Whole state every frame; params MIRROR across the linked preamp pair (Launcher sends [18]=N then [18]=N+1). Disabling sets [19]=[21]=[22]=0. SIDE EFFECTS of enabling: the Launcher also turns on 48V phantom for the pair (SET_PARAM param 0x51) and links the preamp pair (SET_LINK space 0). No readback CATEGORY identified yet in the 0x74/0x75 protocol (the DSP-EQ categories 0x07/0x1a are unmapped -- one of them may cover this); in the passive 0x73 stream only the phantom bit (0x10) moves. build_micmodeling_command(profile, channel, enabled, pattern, swap, model); not in cli.py.\",\"opcode\":\"0x17\",\"opcode_name\":\"SET_MIC_MODELING\",\"opcode_offset\":4,\"param_id\":\"0xe5\",\"param_id_offset\":16,\"pattern_offset\":22,\"pattern_range\":[0,100],\"pattern_range_note\":\"[0,100] is the model-0 (EdgeDuo raw) continuous morph range. For a selected emulation model [22] is a small index whose max is model-dependent: 0 (fixed), 2 (3-way), or 8 (9-detent multipattern). See notes and mic_models.json.\",\"subcmd\":\"0x05\",\"subcmd_offset\":17,\"swap_offset\":21}" },
    DecoderDefinition { id: "decode_state_report", frame_id: "state_report", kind: FrameKind::StateReport, status: Status::Confirmed, metadata: "{\"adat_gain_base_offset\":75,\"bus_block\":{\"base_offset\":28,\"bytes_per_bus\":3,\"level_byte_offset\":0,\"notes\":\"Same 'parallel array, N bytes per slot' idea as gain_base_offset/status_base_offset above, but for output buses instead of input channels: byte offset for bus N = base_offset + bytes_per_bus*N + field_offset. Confirmed for ALL 6 bus ids: 0/1/2/5 via captures mona/hp1/hp2/monb (2026-08, level ramps + dim/mute/mono toggles), and 3/4 (line/reamp) via capture settings-linevol-mute-reampvol-toggle (2026-08, level ramps at offsets 37 and 40 + a mute toggle on bus 3). Every SET_PARAM command in each log matched the very next state_report reading at this formula's offset. reserved_byte_offset (+2) never changed in any capture; true padding, or just never exercised, is unconfirmed. dim/mono were never exercised on buses 3/4 and may not apply to a line/reamp output. NOTE: the status byte's mute bit (0x04) also reads 1 whenever that bus is at level 96 with no mute command -- see params.bus_mute.\",\"reserved_byte_offset\":2,\"status_bits\":{\"dim\":{\"mask\":\"0x08\",\"shift\":3},\"mono\":{\"mask\":\"0x10\",\"shift\":4},\"mute\":{\"mask\":\"0x04\",\"shift\":2}},\"status_byte_offset\":1},\"channel_meter_base_offset\":157,\"channel_meter_notes\":\"CONFIRMED 2026-09-01 (dedicated vumeter recapture): the real per-channel input meters live HERE in the 0x73 state report, at 157 + channel_index for the 12 physical channels. Feeding preamps 1/2/3/4 in turn dropped offsets 157/158/159/160 to the single digits one after another, each returning to ~96 when the tone stopped; unfed channels stayed at 96 / noise-floor jitter. Three identical mirror copies of the whole 12-byte block exist at bases 157, 169 and 221 -- use 157. This supersedes meter_report.channel_meter_base_offset (0x75 @32), which on this unit is NOT per-channel: only its byte 32 is live (a monitor/summed level) and byte 33 is a 0/1 flag that the old 32+channel formula misreads as channel 1 pinned at clip. Resolves the unresolved_state_offsets '157/169/221' entry.\",\"channel_meter_scale\":\"inverted: 0x60 (96) at rest/silence, falls toward 0x00 as level rises. Same scale as meter_report.db_curve (raw ~= -dBFS), reuse that curve.\",\"gain_base_offset\":49,\"magic\":\"0x73\",\"magic_offset\":0,\"notes\":\"Parallel-array layout: all channel gains contiguous from gain_base_offset, all status bytes contiguous from status_base_offset. Formula: status_byte = (phase<<6)|(phantom<<4)|(mode&0x03).\",\"output_trim_block\":{\"byte_offsets\":[24,25],\"fields\":{\"target_0\":{\"byte_offset\":24,\"mask\":\"0x70\",\"notes\":\"3-bit field, value<<4 at offset 24. capture settings-trim-mona-monb-line-panlaw (2026-08): SET_PARAM(0x4b, target=0, value 0..6) -> offset 24 stepped 0x00/0x10/0x20/0x30/0x40/0x50/0x60, i.e. exactly value<<4, every step. Almost certainly the Monitor A output trim (first target swept, capture name order mona/monb/line).\",\"shift\":4},\"target_1\":{\"byte_offset\":25,\"mask\":\"0x1c\",\"notes\":\"3-bit field, value<<2 at offset 25 bits 2-4. Same capture: SET_PARAM(0x4b, target=1, value 0..6) -> 0x00/0x04/0x08/0x0c/0x10/0x14/0x18. Almost certainly Monitor B output trim.\",\"shift\":2},\"target_2\":{\"byte_offset\":25,\"mask\":\"0xe0\",\"notes\":\"3-bit field, value<<5 at offset 25 bits 5-7. Same capture: SET_PARAM(0x4b, target=2, value 0..6) -> 0x00/0x20/0x40/0x60/0x80/0xa0/0xc0. Almost certainly Line output trim.\",\"shift\":5}},\"notes\":\"A small packed block just before bus_block, holding the settings-tab output-trim selectors (param 0x4b). Three targets (0/1/2) confirmed, each a 7-position selector (value 0-6) -- the physical meaning of the 7 steps (dB values? reference levels?) is not known, only that the readback is value<<shift. UNUSED bits so far: offset 24 bits 0-3 and 7, offset 25 bits 0-1 -- offset 25 bits 0-1 (a 2-bit field, 4 options) is a plausible home for the PAN LAW setting, and offset 24 bits 0-3 for a 4th trim target, but the capture named 'panlaw' never actually sent a 4th target or any other param, so pan law is still uncaptured. See params.output_trim.\"},\"sample_rate_byte_offset\":{\"notes\":\"The device sample-rate INDEX (0-6, see params.sample_rate.values), one plain byte. CONFIRMED from capture macos-smplrt-32k-44k1-48-88k2-96k-176k4-192k (2026-08, native macOS): the user stepped 32k/44k1/48k/88k2/96k/176k4/192k; each SET_GLOBAL(param 0x03, value V) was followed ~1 s later (device clock re-lock settle) by offset 18 == V, monotonic 0..6. This overlaps the old 'offset 17/19 blip' region -- offset 18 itself is the sample rate, NOT blip noise; 17 and 19 are still the ~3 s Launcher-handshake blip. Also-moved-at-88k2/176k4 offsets 21/22/23/27 are undecoded clock/PLL/buffer state (see unresolved_state_offsets). See params.sample_rate.\",\"offset\":18},\"screen_brightness_byte_offset\":{\"notes\":\"The device's front-panel screen brightness, 0-100 (0x00-0x64), one plain byte. CONFIRMED from capture macos-scrbrght-0-100-50-multvalue (2026-08, native macOS -- the user watched the physical screen dim/brighten in real time): every SET_PARAM(opcode 0x12, param 0x0e, value V) was followed by offset 26 == V in the very next 0x73 report, 25/25 commands, values 0x00..0x64. So screen brightness IS a real, persisted, readable device setting (NOT host-side -- the earlier settings-scrbrght-surroundEQ capture under the VM simply never reached the device / the slider did nothing under the VM). Sits in the previously-unmapped gap between output_trim_block (24-25) and bus_block (28-45). Offset 27 still unmapped. See params.screen_brightness.\",\"offset\":26},\"spdif_gain_base_offset\":91,\"status_base_offset\":61,\"status_bits\":{\"input_mode\":{\"mask\":\"0x03\",\"shift\":0},\"phantom\":{\"mask\":\"0x10\",\"shift\":4},\"phase_invert\":{\"mask\":\"0x40\",\"shift\":6}},\"talkback_block\":{\"gain_byte_offset\":74,\"notes\":\"Sits immediately after the 12-byte channel status array (status_base_offset 61 + 12 = 73). offset 73 is a packed talkback status byte (see status_bits); offset 74 is the talkback gain (0-96, same scale as bus_level, 96=0dB) of the CURRENTLY SELECTED source -- confirmed from talkback-gain-int-ch1-2-12 (2026-08): sweeping param 0x20 moved offset 74 1:1 across 0-96, and re-selecting the source reset offset 74 to that source's own stored gain (so talkback gain is per-source, but only the selected source's value is visible here). CAVEAT: source_low and dest_assign share bits 2-3 (source index 4-12 sets bits that also mean dest0/dest1 assigned). The talkback-select and talkback-bttn captures were separate sessions -- source was 0 during the dest toggles and no dest/button was set during the source sweep -- so how these coexist in one byte when both are non-default is UNTESTED. Needs a combined capture before trusting the readback with talkback fully configured.\",\"status_bits\":{\"button\":{\"mask\":\"0x40\",\"notes\":\"Talkback button / hold-to-talk active. Confirmed from capture talkback-bttn (2026-08): press -> bit 6 set, release -> cleared, every time.\",\"shift\":6},\"dest_assign\":{\"mask\":\"0x3c\",\"notes\":\"4-bit bitmask, one bit per talkback destination (Mon A / Mon B / HP1 / HP2): destination N assigned = bit (N+2), i.e. dest0=0x04, dest1=0x08, dest2=0x10, dest3=0x20. Confirmed from capture talkback-bttn (2026-08): toggling each of the 4 switches in isolation set/cleared exactly its bit. Multi-destination combining is USER-CONFIRMED (2026-08) -- talkback can be sent to all 4 at once, so this byte can legitimately hold several of these bits set together.\",\"shift\":2},\"source_low\":{\"mask\":\"0x03\",\"notes\":\"LOW 2 BITS of the talkback source index only. Confirmed from capture talkback-select (2026-08): selecting sources 0..12 in turn, offset 73 bits 0-1 always equalled source_index & 0x03 (13/13 samples). The high bits of the source index are NOT exposed anywhere found in the 0x73 report -- offsets 72 and 75 stayed 0x00 for the whole sweep. So you can read talkback source back only mod 4 from the device; track the full value client-side.\",\"shift\":0}},\"status_byte_offset\":73}}" },
    DecoderDefinition { id: "decode_meter_report", frame_id: "meter_report", kind: FrameKind::MeterReport, status: Status::Unknown, metadata: "{\"channel_meter_base_offset\":32,\"channel_meter_scale\":\"inverted: 0x60 (96) at rest/silence, falls toward 0x00 as level rises\",\"db_curve\":[[0,0],[10,-10],[12,-12],[20,-20],[30,-30],[40,-40],[60,-60]],\"db_curve_notes\":\"Channel 0 only, 1kHz sine, gain swept down from max while phase_invert was clicked as a timestamp marker at each reference point (a real command, so it shows up as an unambiguous status-byte bit flip -- a cheap way to bookmark a capture without a second command-frame log). Raw byte == -dB, essentially exactly, across the whole 0 to -60dB range swept (the -60 point originally logged as raw=59, not 60, but that was the user eyeballing a color bar rather than a number while manually dragging the gain slider -- not curve non-linearity, corrected to 60). Not yet swept: the red/orange LED boundary, and anything past -60dB (one stray, unexplained data point -- raw=72 at gain driven to 0/deep silence -- doesn't fit this line at all, but wasn't a deliberate reference point, see notes above). Not yet confirmed on other channels, but likely identical given the same offset formula holds for all 12.\",\"led_scale\":{\"bands\":[{\"clip\":true,\"color\":\"red\",\"max_db\":null,\"min_db\":0},{\"clip\":false,\"color\":\"orange\",\"max_db\":0,\"min_db\":-4},{\"clip\":false,\"color\":\"yellow\",\"max_db\":-4,\"min_db\":-12},{\"clip\":false,\"color\":\"green\",\"max_db\":-12,\"min_db\":null}],\"clip_at_db\":0,\"notes\":\"Confirmed 2026-08: no separate solid-red band below clip -- orange runs all the way to 0dB, red only appears at clip.\"},\"magic\":\"0x75\",\"magic_offset\":0,\"notes\":\"CORRECTED 2026-09-01: on this unit the 0x75 frame is NOT a per-channel meter. Only byte 32 is live -- a monitor/summed level that moves for any input -- and byte 33 is a 0/1 flag. The old '32 + channel, confirmed for all 12' claim was wrong: a dedicated recapture feeding preamps 1-4 in turn showed no movement past byte 32, and the byte-33 flag was rendered as channel 1 stuck at clip. The real per-channel input meters are in the 0x73 state report -- see state_report.channel_meter_base_offset (157 + channel). db_curve below (raw ~= -dBFS) still applies to those. Kept here for the offset-32 monitor reading and the shared curve.\",\"status\":\"superseded_for_per_channel\"}" },
    DecoderDefinition { id: "decode_init_enumeration_report", frame_id: "init_enumeration_report", kind: FrameKind::InitEnumerationReport, status: Status::Unconfirmed, metadata: "{\"magic\":\"0x74\",\"magic_offset\":0,\"notes\":\"This burst IS the readback protocol (frame.readback) -- the Launcher walking every (category, index). Decoded 2026-08-31: the host SENDS a 0x74 request `74 00 00 00 10 00 00 00 <cat> 00 00 00 <idx> 00 00 00` on EP 0x01 OUT and the device REPLIES with `75 00 00 00 40 01 00 00 <cat> ... <idx> ... <data>` on EP 0x82 IN. It is not names-only and not one-shot -- it carries live state (routing = cat 0x03, mixer = cat 0x04, AuraVerb = cat 0x0a, ...). The text below is the original (pre-decode) analysis of the connect burst, kept for the emission-order detail. A one-shot device topology enumeration. Seen ONLY in all_reports_AntelopeINIT.tsv (113 records, t=7.5-16s of the connect sequence), never in any other capture. That capture is the Antelope Launcher being launched with NO user interaction (confirmed by the user) -- so this whole burst, and the single outgoing 0x70/SET_PARAM(param 0x49) at t=7.71s, is the Launcher's automatic startup/handshake, not anything a user did. Full emission order (see PROTOCOL.md section 4): 0x11 x2 (S/PDIF); 0x0b marker; 0x1b x1 singleton; 0x1a x16 (ADAT -- confirmed); 0x03 x15 (unmapped); 0x04 x4 (unmapped, each entry trailed by its own 0x0b=3 marker); 0x0a x1, 0x15 x1, 0x16 x1 singletons; 0x19 x64 (unmapped -- almost certainly the 64-channel USB/Thunderbolt stream, the device's headline I/O count; routing command's first payload byte 0x41=65 is consistent with a 1-based index into a 64-entry space); 0x0b closing markers. 0x0b (8 records, index values 1/2/3/3/3/3/0/4) is a section/phase marker, NOT an I/O category. Confirmed: 0x1a=ADAT, 0x11=S/PDIF. Still unnamed: 0x19/0x03/0x04 and the four singletons. NOTE (2026-08): checked all 21 raw pcapng files -- NOT ONE contains a USB string-descriptor fetch, and the UAC2 descriptor is a stub with no channel names. So the names are Launcher-internal and cannot be recovered from any capture on file; the practical routes are (a) a fresh connect capture where Windows re-fetches string descriptors, or (b) reading the counts off against the Launcher's routing-tab labels. This is NOT a live settings readback -- indices only, no current values. Listed here mainly so scan tools stop flagging 0x74 as unknown. CROSS-PLATFORM CONFIRMED (2026-08): the four native-macOS INIT captures (macos-antelopeINIT-*) reproduce this exactly -- same 0x74 burst (byte-identical between captures with different device state), and the SAME single outgoing handshake frame SET_PARAM(param 0x49, channel 1, value 0). That one 0x49 frame is the ENTIRE host->device connect handshake; everything else the Launcher does at connect is either passive polling or cosmetic state restore (a SET_PARAM(gain 0x50) fade-in ramp). macOS capture layout: 40-byte Darwin pseudo-header + 320-byte payload (frame.len==360), payload byte 0 = magic; 0x74 arrives on IN endpoint 1, 0x73/0x75 on IN endpoint 2.\",\"record_layout\":\"header 0x74, u32 constant 0x10 @4, u32 category_id @8, u32 index @12 (0-based, 0..count-1 within a category); nothing non-zero past offset 16. Records carry (category_id, index) ONLY -- no names (names would be USB string descriptors, i.e. control transfers, not in the 320-byte HID capture).\",\"status\":\"unconfirmed\"}" },
    DecoderDefinition { id: "decode_readback", frame_id: "readback", kind: FrameKind::Decoder, status: Status::Confirmed, metadata: "{\"categories\":{\"0x00\":\"device id + firmware (ascii '4.41' seen)\",\"0x01\":\"model name ('OrionStudio_III') + serial + hw rev ('7.0') -- CONTAINS THE DEVICE SERIAL, do not commit raw dumps\",\"0x02\":\"per-channel present flag (scalar 0x01), indexed 0..63\",\"0x03\":\"ROUTING MATRIX -- one record per destination group, index = dest_id 0..14. Record = <dest_id> then a (source_bank, source_index) pair per output channel of that group (destination_channels[dest_id] pairs), identical layout to the frame.routing_command write frame. VERIFIED byte-identical against CLI-written routes 2026-08-31.\",\"0x04\":\"VIRTUAL MIXER -- one record per mix, index = mix number 0..3 (= Mix 1..4). Record = a flat array of 33 three-byte slots, SAME field order as the frame.mix_command write frame: <fader> <pan|mute|solo> <send>. Slot index maps 1:1 onto frame.mix_command's `channel` field with NO special case: slot 0 = the MIX MASTER strip, slots 1..32 = the 32 input strips. 99 bytes on the wire, zero-padded to the report size. DECODED + HARDWARE-CONFIRMED, both halves. (a) INPUTS, 2026-08-31: wrote mix 1 / ch 5 / fader 40 / pan +12 / mute / send 33 (frame bytes `28 6c 21`), read the record back and slot 5 was `28 6c 21` with NO other slot changed; three reads 2.5s apart -- and later 142 reads over 150s -- were byte-identical, so the third byte is stored send state and not a live meter. (b) MASTER, 2026-09-01: a usbmon capture of the Launcher sweeping the Mix 1 master fader (captures/new/mix1-masterfaderplay.pcapng) is 68 frames, every one `d4 05 00 00 <fader> 20 60` -- mix 0, CHANNEL 0, pan and send constant; the sweep ended at fader 90 and slot 0 then read back as -90 dB. The Launcher itself addresses channel 0, so it is a normal target and NOT an out-of-range write. protocol.parse_mixer_record; CLI `mix-status`. This is the mixer readback that frame.mix_command's notes used to say did not exist -- it is not in the 0x73 state report, it is here.\",\"0x05\":\"preamp channel summary (gain/status), ~12 bytes\",\"0x06\":\"channel status bits (mirrors state_report offsets 61+)\",\"0x07\":\"EQ curve -- frequency points ~30/200/1k/5k/15k Hz, 8 records. Channel or surround EQ. Undecoded.\",\"0x0a\":\"AuraVerb parameters (mirrors frame.auraverb_command payload). Partially decoded.\",\"0x0b\":\"scalar 0x01\",\"0x0c\":\"~90-entry per-channel link/config table. Undecoded.\",\"0x0d\":\"scalar (0x18)\",\"0x11\":\"S/PDIF + a capability bitmask block (128 bytes)\",\"0x12\":\"scalar (clock source or sample-rate index?)\",\"0x15\":\"~90-entry table, sibling of 0x0c\",\"0x16\":\"output trim / pan-law scalars (two 0x32 values + flags)\",\"0x19\":\"64 entries, all empty in the connect walk -- the 64-ch USB/TB stream slots\",\"0x1a\":\"EQ curve, 8 bands x freq points ~30..14000 Hz (116 bytes). Undecoded.\",\"0x1b\":\"mixer bus level/range table (repeating 50 00 50 00 58 02 00). Undecoded.\",\"note\":\"Categories 0x1c..0x60 answer but with empty bodies (probed 2026-08-31). Full raw enumeration: tools/readback_enum.py.\"},\"category_counts\":{\"0x03\":15,\"0x04\":4,\"0x0a\":1,\"0x0b\":8,\"0x11\":2,\"0x15\":1,\"0x16\":1,\"0x19\":64,\"0x1a\":16,\"0x1b\":1},\"category_counts_note\":\"Record counts taken from the device's OWN 0x74 connect enumeration (frame.init_enumeration_report -- 113 records = 16+2+64+15+4+4+8, so these ten categories are the whole walk). This is the only evidence-grade count we have and it is the safe query bound (see .hazard). Categories that answer but do NOT appear in the connect walk (0x00, 0x01, 0x02, 0x05, 0x06, 0x07, 0x0c, 0x0d, 0x12) have NO known count -- protocol.build_readback_query cannot bound them, so treat any index above 0 on those as unproven and dangerous. Note that cat 0x03 answers with distinct bodies at idx 15-24 even though it only has 15 destination groups: that is already adjacent memory, not extra routing data.\",\"category_offset\":8,\"cli\":\"protocol.build_readback_query (bounds-checked) / check_readback_index / readback_category_count / is_readback_response / readback_body / parse_routing_record (cat 0x03) / parse_mixer_record (cat 0x04); transport.HidTransport.query; CLI `readback <cat> [idx]` (raw), `matrix-status` (live cat-0x03 read, falls back to the cache if the device is unreachable) and `mix-status [mix]` (live cat-0x04 read).\",\"data_offset\":16,\"discriminator_note\":\"The response magic is 0x75 but byte 1 = 0x00. The free-running METER report is also magic 0x75 but byte 1 = 0x1f; the STATE report (frame.state_report) is the same family with magic 0x73 -- effectively 'category 0, pushed continuously'. So (magic 0x75 AND byte1 0x00 AND category AND index) uniquely identifies a readback response amid the ~250 Hz state/meter stream.\",\"hazard\":\"DO NOT QUERY AN INDEX PAST A CATEGORY'S RECORD COUNT. The firmware does not bounds-check the index: one index past the end returns adjacent memory with a WRONG layout, and a little further it faults. Confirmed 2026-08-31 on real hardware -- `category 0x04 index 5` hard-crashed the Orion Studio III (front panel: 'CRITICAL ERROR! / Failure.c / L: 204  E: 0 / BusFault_Handler' -- a Cortex-M BusFault) and the unit needed a physical power cycle. Diagnostic signature, in order: cat 0x04 idx 0-3 = four same-layout mixer records; idx 4 = answers but with a completely different layout (a float32 table = adjacent memory); idx 5 = NO response at all, then the OUT endpoint is dead. An EMPTY answer is normal; NO answer means the MCU just died inside the handler. NOTE: this supersedes the earlier diagnosis that the endpoint halt was caused by 'hammering' / query rate -- the 2026-08-31 crash took about ten slow queries. Rate was never the trigger; the out-of-range index was. Enforced by protocol.check_readback_index against readback.category_counts.\",\"history\":\"Before 2026-08-31 the project concluded there was NO USB readback (see params.routing.readback, PROTOCOL.md, the -poke test). That was wrong: the request just needs the 10-00-00-00 sub-header + a (category,index) -- a bare 0x74 is ignored. The cross-machine persistence the user reported was the device reporting its NVRAM routing to a fresh Launcher via exactly this, not account sync.\",\"identity\":{\"_comment\":\"LAYOUT ONLY -- the serial VALUE is never stored in this repo. It is read from the hardware on request (CLI `identity --serial`). Same record shape on the Orion Studio III and the Zen Go Synergy Core, so it is probably family-wide.\",\"category\":\"0x01\",\"firmware_category\":\"0x00\",\"firmware_offset\":8,\"name_offset\":0,\"notes\":\"Category 0x01 is a 48-byte record of NUL-terminated ASCII at fixed offsets: model name @0, SERIAL @20 (13 chars), hardware revision @36, then 4 binary bytes @44 (little-endian u32; both units seen decode to mid-2021, so plausibly a build/calibration timestamp -- a GUESS, not confirmed). Category 0x00 is a separate record: 12 bytes with an ASCII firmware version at offset 8 (e.g. '4.41'). Parsed by protocol.parse_identity_record / parse_firmware_record.\",\"revision_offset\":36,\"serial_offset\":20,\"stamp_offset\":44},\"index_offset\":12,\"liveness\":\"The device answers EVERY (category, index) that is IN RANGE -- one it has no record for just comes back with an empty body. 'has a non-empty body' is the real liveness signal. Scalar categories return the same record for every index. Pace queries and reopen on halt (tools/readback_enum.py, transport.HidTransport.query).\",\"magic_offset\":0,\"request\":\"host->device, EP 0x01 OUT, full 320-byte report: 74 00 00 00 | 10 00 00 00 | <category> 00 00 00 | <index> 00 00 00 | 00...  (magic 0x74 @0, subcmd 0x10 @4, category @8, index @12)\",\"request_magic\":\"0x74\",\"response\":\"device->host, EP 0x82 IN, full 320-byte report: 75 00 00 00 | 40 01 00 00 | <category> 00 00 00 | <index> 00 00 00 | <data...>  (magic 0x75 @0, discriminator 0x00 @1, category @8, index @12, payload from @16)\",\"response_discriminator\":\"0x00\",\"response_discriminator_offset\":1,\"response_magic\":\"0x75\",\"status\":\"DECODED 2026-08-31 (CAPTURE E' -- usbmon on the Linux host while the Windows Launcher connected over QEMU USB passthrough -- then replayed directly from Linux, tools/readback_enum.py). This is the device-side readback the earlier analysis had concluded did not exist. It is an in-band request/response on the SAME HID interrupt endpoints, NOT a HID Feature report and NOT a control transfer -- which is why tools/hid_probe.py (no Feature report, GET_REPORT STALLs) and tools/readback_probe.py did not find it.\",\"subcmd\":\"0x10\",\"subcmd_offset\":4}" },
    DecoderDefinition { id: "decode_error_response", frame_id: "error_response", kind: FrameKind::ErrorResponse, status: Status::Unconfirmed, metadata: "{\"magic\":\"0x61\",\"magic_offset\":0,\"notes\":\"On the Discrete 8 Pro (peer PR): the device replies with a 0x61 frame (status byte at offset 4) ONLY when it receives an opcode it does not recognise; a recognised opcode is answered with silence. IMPORTANT: silence means 'opcode recognised', NOT 'command took effect' -- on that device opcode 0x14 was silent and did nothing. No 0x61 frame has ever appeared in an Orion capture (only 0x70/0x73/0x75/0x74), but the Launcher never sends Orion a bad opcode, so absence is not evidence. If you ever probe a candidate opcode on Orion, watch for a 0x61 reply -- and don't read silence as success.\",\"status\":\"unconfirmed on Orion -- confirmed on the sibling Discrete 8 Pro\",\"status_offset\":4,\"status_values\":{\"0x10\":\"unknown opcode\"}}" },
];
